const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Helper to generate items with variations
const makeProduct = (category, brand, name, price, discountPrice, shortDesc, desc, img1, img2, tags) => ({
  name,
  shortDescription: shortDesc,
  description: desc,
  price,
  discountPrice,
  category,
  brand,
  images: img2 ? [img1, img2] : [img1],
  countInStock: Math.floor(Math.random() * 40) + 15,
  rating: Number((4.3 + Math.random() * 0.7).toFixed(1)),
  numReviews: Math.floor(Math.random() * 180) + 25,
  tags: [category.toLowerCase(), brand.toLowerCase(), ...tags]
});

